def get_alerts(state, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0106000" if __import__("os").path.isdir("./environment_mix/0106000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.astimezone(datetime.timezone.utc) if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_log(api_client_id, params_obj, http_status, served_from_cache, error_code=None):
        logs = _load("request_logs.json")
        latency_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": _new_id("wthr_req"),
            "api_client_id": api_client_id,
            "tool_name": "get-alerts",
            "params": params_obj,
            "state": params_obj.get("state"),
            "latitude": None,
            "longitude": None,
            "response_status_code": int(http_status),
            "served_from_cache": bool(served_from_cache),
            "latency_ms": int(latency_ms),
            "error_code": error_code,
            "created_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(state, str):
        _append_log(None, {"state": state}, 400, True, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "state must be a string of length 2")
    st = state.strip().upper()
    if len(st) != 2:
        _append_log(None, {"state": state}, 400, True, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "state must be exactly 2 characters")

    # Ambient auth: choose any active client that can consume tools (not suspended/revoked)
    clients = _load("api_clients.json")
    active_client = None
    for c in clients:
        if isinstance(c, dict) and c.get("status") == "active":
            active_client = c
            break
    if not active_client:
        _append_log(None, {"state": st}, 401, True, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API client is available to serve this request.")

    # Quota enforcement (rolling minute and UTC day) using request_logs
    logs = _load("request_logs.json")
    client_id = active_client.get("id")
    quota_min = active_client.get("quota_requests_per_minute")
    quota_day = active_client.get("quota_requests_per_day")
    if not isinstance(quota_min, int) or quota_min < 0:
        quota_min = 0
    if not isinstance(quota_day, int) or quota_day < 0:
        quota_day = 0

    one_min_ago = now - datetime.timedelta(minutes=1)
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
    used_min = 0
    used_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_client_id") != client_id:
            continue
        dt = _parse_rfc3339(r.get("created_at"))
        if not dt:
            continue
        if dt >= one_min_ago:
            used_min += 1
        if dt >= day_start:
            used_day += 1

    if quota_min == 0 or used_min >= quota_min:
        _append_log(client_id, {"state": st}, 429, True, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Per-minute request quota exceeded.", quota_requests_per_minute=quota_min)
    if quota_day == 0 or used_day >= quota_day:
        _append_log(client_id, {"state": st}, 429, True, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=quota_day)

    # Lookup alerts; transition expired-by-time to expired (best-effort synchronous)
    alerts = _load("weather_alerts.json")
    changed = False
    active = []
    for a in alerts:
        if not isinstance(a, dict):
            continue
        if (a.get("state") or "").upper() != st:
            continue
        expires_at = _parse_rfc3339(a.get("expires_at"))
        if a.get("status") == "active" and expires_at is not None and expires_at < now:
            # transition active -> expired is legal
            a["status"] = "expired"
            a["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            changed = True
        if a.get("status") != "active":
            continue
        expires_at2 = _parse_rfc3339(a.get("expires_at"))
        if expires_at2 is not None and expires_at2 < now:
            continue
        active.append(a)

    if changed:
        _save("weather_alerts.json", alerts)

    if not active:
        _append_log(client_id, {"state": st}, 404, True, "NOT_FOUND")
        return _err("NOT_FOUND", "No active alert data available for that state.", state=st)

    # Update last_seen_at on successful request
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            c["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            _save("api_clients.json", clients)
            break

    _append_log(client_id, {"state": st}, 200, True, None)
    return {"alerts": active, "state": st, "count": len(active)}

def get_forecast(latitude, longitude, **_extra):
    import json, os, datetime, time, math, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0106000" if __import__("os").path.isdir("./environment_mix/0106000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:


                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(request_logs, api_client_id, params, response_status_code, served_from_cache, latency_ms, error_code):
        now = _now_utc()
        log = {
            "id": "rql_" + uuid.uuid4().hex,
            "api_client_id": api_client_id,
            "tool_name": "get-forecast",
            "params": params,
            "state": None,
            "latitude": params.get("latitude"),
            "longitude": params.get("longitude"),
            "response_status_code": int(response_status_code),
            "served_from_cache": bool(served_from_cache),
            "latency_ms": int(max(0, latency_ms)),
            "error_code": error_code,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        request_logs.append(log)
        _save("request_logs.json", request_logs)

    t0 = time.perf_counter()

    # Validation
    if not isinstance(latitude, (int, float)) or isinstance(latitude, bool):
        latency = int((time.perf_counter() - t0) * 1000)
        logs = _load("request_logs.json")
        _log_request(logs, None, {"latitude": latitude, "longitude": longitude}, 400, True, latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "latitude must be a number between -90 and 90")
    if not isinstance(longitude, (int, float)) or isinstance(longitude, bool):
        latency = int((time.perf_counter() - t0) * 1000)
        logs = _load("request_logs.json")
        _log_request(logs, None, {"latitude": latitude, "longitude": longitude}, 400, True, latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "longitude must be a number between -180 and 180")
    if latitude < -90 or latitude > 90:
        latency = int((time.perf_counter() - t0) * 1000)
        logs = _load("request_logs.json")
        _log_request(logs, None, {"latitude": latitude, "longitude": longitude}, 400, True, latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "latitude out of range")
    if longitude < -180 or longitude > 180:
        latency = int((time.perf_counter() - t0) * 1000)
        logs = _load("request_logs.json")
        _log_request(logs, None, {"latitude": latitude, "longitude": longitude}, 400, True, latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "longitude out of range")

    api_clients = _load("api_clients.json")
    request_logs = _load("request_logs.json")

    now = _now_utc()
    one_min_ago = now - datetime.timedelta(minutes=1)
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

    def _count_logs(cid, since_dt):
        c = 0
        for r in request_logs:
            if r.get("api_client_id") != cid:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= since_dt:
                c += 1
        return c

    chosen = None
    for c in api_clients:
        if c.get("status") != "active":
            continue
        qpm = c.get("quota_requests_per_minute")
        qpd = c.get("quota_requests_per_day")
        if not isinstance(qpm, int) or qpm < 0:
            continue
        if not isinstance(qpd, int) or qpd < 0:
            continue
        used_m = _count_logs(c.get("id"), one_min_ago)
        used_d = _count_logs(c.get("id"), day_start)
        if used_m >= qpm:
            continue
        if used_d >= qpd:
            continue
        chosen = c
        break

    if chosen is None:
        any_active = any(c.get("status") == "active" for c in api_clients)
        latency = int((time.perf_counter() - t0) * 1000)
        code = "UNAUTHORIZED"
        status = 401
        if any_active:
            code = "RATE_LIMIT"
            status = 429
        _log_request(request_logs, None, {"latitude": float(latitude), "longitude": float(longitude)}, status, True, latency, code)
        return _err(code, "No authorized client available to serve request at this time")

    forecast_points = _load("forecast_points.json")
    forecasts = _load("forecasts.json")

    # Nearest active forecast_point (simple equirectangular approximation)
    best = None
    best_d = None
    lat0 = float(latitude)
    lon0 = float(longitude)

    for p in forecast_points:
        if p.get("status") != "active":
            continue
        plat = p.get("latitude")
        plon = p.get("longitude")
        if not isinstance(plat, (int, float)) or isinstance(plat, bool):
            continue
        if not isinstance(plon, (int, float)) or isinstance(plon, bool):
            continue
        # approximate distance squared in degrees adjusted by cos(lat)
        x = (float(plon) - lon0) * math.cos(math.radians((float(plat) + lat0) / 2.0))
        y = float(plat) - lat0
        d2 = x * x + y * y
        if best is None or d2 < best_d:
            best = p
            best_d = d2

    if best is None:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, chosen.get("id"), {"latitude": lat0, "longitude": lon0}, 404, True, latency, "NOT_FOUND")
        return _err("NOT_FOUND", "No supported forecast grid point for provided location")

    # Latest available forecast for this point
    fp_id = best.get("id")
    best_fc = None
    best_issued = None
    for f in forecasts:
        if f.get("forecast_point_id") != fp_id:
            continue
        if f.get("status") != "available":
            continue
        issued = _parse_dt(f.get("issued_at"))
        if issued is None:
            continue
        if issued.tzinfo is None:
            issued = issued.replace(tzinfo=datetime.timezone.utc)
        if best_fc is None or issued > best_issued:
            best_fc = f
            best_issued = issued

    if best_fc is None:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, chosen.get("id"), {"latitude": lat0, "longitude": lon0}, 404, True, latency, "NOT_FOUND")
        return _err("NOT_FOUND", "No available forecast for nearest supported grid point")

    # Success: log and update last_seen_at
    chosen["last_seen_at"] = _iso(now)
    chosen["updated_at"] = _iso(now)
    _save("api_clients.json", api_clients)

    latency = int((time.perf_counter() - t0) * 1000)
    _log_request(request_logs, chosen.get("id"), {"latitude": lat0, "longitude": lon0}, 200, True, latency, None)

    return {
        "data": {
            "requested_location": {"latitude": lat0, "longitude": lon0},
            "forecast_point": best,
            "forecast": best_fc,
        },
        "meta": {
            "served_from_cache": True,
        },
    }

def get_api_client(api_key, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0106000" if __import__("os").path.isdir("./environment_mix/0106000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(request_logs, api_client_id, response_status_code, latency_ms, error_code):
        now = _now_utc()
        log = {
            "id": "rql_" + uuid.uuid4().hex,
            "api_client_id": api_client_id,
            "tool_name": "get-forecast",  # constrained enum doesn't include get-api-client; log as closest read tool.
            "params": {"api_key_present": api_key is not None},
            "state": None,
            "latitude": None,
            "longitude": None,
            "response_status_code": int(response_status_code),
            "served_from_cache": True,
            "latency_ms": int(max(0, latency_ms)),
            "error_code": error_code,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        request_logs.append(log)
        _save("request_logs.json", request_logs)

    t0 = time.perf_counter()

    if not isinstance(api_key, str) or not api_key:
        latency = int((time.perf_counter() - t0) * 1000)
        logs = _load("request_logs.json")
        _log_request(logs, None, 401, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing or invalid")

    api_clients = _load("api_clients.json")
    request_logs = _load("request_logs.json")

    # Authenticate: accept direct id match OR exact hash match of the provided key.
    key_hash = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
    client = None
    for c in api_clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key or c.get("api_key_hash") == key_hash:
            client = c
            break

    if client is None:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, None, 401, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing or invalid")

    if client.get("status") != "active":
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, client.get("id"), 403, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client is not permitted to query identity in current status", status=client.get("status"))

    now = _now_utc()
    one_min_ago = now - datetime.timedelta(minutes=1)
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

    def _count_logs_since(since_dt):
        c = 0
        for r in request_logs:
            if r.get("api_client_id") != client.get("id"):
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= since_dt:
                c += 1
        return c

    used_minute = _count_logs_since(one_min_ago)
    used_day = _count_logs_since(day_start)

    # Log successful identity query (as get-forecast due to tool enum limitation)
    client["last_seen_at"] = _iso(now)
    client["updated_at"] = _iso(now)
    _save("api_clients.json", api_clients)

    latency = int((time.perf_counter() - t0) * 1000)
    _log_request(request_logs, client.get("id"), 200, latency, None)

    return {
        "data": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "quota": {
                "requests_per_minute": client.get("quota_requests_per_minute"),
                "requests_per_day": client.get("quota_requests_per_day"),
            },
            "usage": {
                "requests_last_minute": used_minute,
                "requests_today_utc": used_day,
            },
            "timestamps": {
                "created_at": client.get("created_at"),
                "updated_at": client.get("updated_at"),
                "last_seen_at": client.get("last_seen_at"),
            },
        }
    }

def upsert_weather_alert(api_key, upstream_provider, upstream_alert_id, state, event, severity, urgency, certainty, headline, description_text, status, effective_at=None, expires_at=None, ingested_at=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0106000" if __import__("os").path.isdir("./environment_mix/0106000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(request_logs, api_client_id, params, response_status_code, served_from_cache, latency_ms, error_code):
        now = _now_utc()
        log = {
            "id": "rql_" + uuid.uuid4().hex,
            "api_client_id": api_client_id,
            "tool_name": "get-alerts",  # tool enum doesn't include upsert; log as closest alerts tool.
            "params": params,
            "state": params.get("state"),
            "latitude": None,
            "longitude": None,
            "response_status_code": int(response_status_code),
            "served_from_cache": bool(served_from_cache),
            "latency_ms": int(max(0, latency_ms)),
            "error_code": error_code,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        request_logs.append(log)
        _save("request_logs.json", request_logs)

    t0 = time.perf_counter()

    # Validate auth param type
    if not isinstance(api_key, str) or not api_key:
        latency = int((time.perf_counter() - t0) * 1000)
        logs = _load("request_logs.json")
        _log_request(logs, None, {"state": None}, 401, True, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing or invalid")

    # Validate required fields / enums
    if not isinstance(upstream_provider, str):
        return _err("VALIDATION_ERROR", "upstream_provider must be a string")
    if upstream_provider not in ("nws", "meteo", "other"):
        return _err("VALIDATION_ERROR", "Invalid upstream_provider enum")
    # Stored schema enum only allows 'nws'
    if upstream_provider != "nws":
        return _err("VALIDATION_ERROR", "upstream_provider must be 'nws' for this datastore schema")

    if not isinstance(upstream_alert_id, str) or len(upstream_alert_id) < 1:
        return _err("VALIDATION_ERROR", "upstream_alert_id must be a non-empty string")

    if not isinstance(state, str) or len(state) != 2:
        return _err("VALIDATION_ERROR", "state must be exactly 2 characters")
    state_u = state.upper()

    for nm, val in (("event", event), ("headline", headline), ("description_text", description_text)):
        if not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string")

    if severity not in ("unknown", "minor", "moderate", "severe", "extreme"):
        return _err("VALIDATION_ERROR", "Invalid severity enum")
    if urgency not in ("unknown", "past", "future", "expected", "immediate"):
        return _err("VALIDATION_ERROR", "Invalid urgency enum")
    if certainty not in ("unknown", "unlikely", "possible", "likely", "observed"):
        return _err("VALIDATION_ERROR", "Invalid certainty enum")
    if status not in ("active", "expired", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status enum")

    eff_dt = _parse_dt(effective_at) if effective_at is not None else None
    if effective_at is not None and eff_dt is None:
        return _err("VALIDATION_ERROR", "effective_at must be RFC3339 date-time or null")

    exp_dt = _parse_dt(expires_at) if expires_at is not None else None
    if expires_at is not None and exp_dt is None:
        return _err("VALIDATION_ERROR", "expires_at must be RFC3339 date-time or null")

    ing_dt = _parse_dt(ingested_at) if ingested_at is not None else None
    if ingested_at is not None and ing_dt is None:
        return _err("VALIDATION_ERROR", "ingested_at must be RFC3339 date-time or null")

    if eff_dt is not None and exp_dt is not None:
        # Normalize tz if missing
        if eff_dt.tzinfo is None:
            eff_dt = eff_dt.replace(tzinfo=datetime.timezone.utc)
        if exp_dt.tzinfo is None:
            exp_dt = exp_dt.replace(tzinfo=datetime.timezone.utc)
        if eff_dt > exp_dt:
            return _err("VALIDATION_ERROR", "effective_at must be <= expires_at when both provided")

    api_clients = _load("api_clients.json")
    request_logs = _load("request_logs.json")

    # Authenticate explicitly by id or stored hash match of provided key.
    key_hash = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
    client = None
    for c in api_clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key or c.get("api_key_hash") == key_hash:
            client = c
            break
    if client is None:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, None, {"state": state_u}, 401, True, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing or invalid")

    if client.get("status") != "active":
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, client.get("id"), {"state": state_u}, 403, True, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client not permitted to ingest alerts in current status", status=client.get("status"))

    # Enforce quota for this client
    now = _now_utc()
    one_min_ago = now - datetime.timedelta(minutes=1)
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

    def _count_logs(cid, since_dt):
        c = 0
        for r in request_logs:
            if r.get("api_client_id") != cid:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= since_dt:
                c += 1
        return c

    qpm = client.get("quota_requests_per_minute")
    qpd = client.get("quota_requests_per_day")
    if not isinstance(qpm, int) or qpm < 0 or not isinstance(qpd, int) or qpd < 0:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, client.get("id"), {"state": state_u}, 401, True, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client quota configuration invalid")

    used_m = _count_logs(client.get("id"), one_min_ago)
    used_d = _count_logs(client.get("id"), day_start)

    if used_m >= qpm:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, client.get("id"), {"state": state_u}, 429, True, latency, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Per-minute request quota exceeded")
    if used_d >= qpd:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, client.get("id"), {"state": state_u}, 429, True, latency, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Per-day request quota exceeded")

    alerts = _load("weather_alerts.json")

    # Find existing by natural key
    existing = None
    for a in alerts:
        if a.get("upstream_provider") == upstream_provider and a.get("upstream_alert_id") == upstream_alert_id:
            existing = a
            break

    # Lifecycle transitions
    transitions = {
        "active": {"expired", "cancelled"},
        "expired": set(),
        "cancelled": set(),
    }

    if ing_dt is None:
        ing_dt = now

    if existing is None:
        # Create
        new_id = "wxa_" + uuid.uuid4().hex
        if status == "available":
            pass
        row = {
            "id": new_id,
            "upstream_provider": upstream_provider,
            "upstream_alert_id": upstream_alert_id,
            "state": state_u,
            "event": event,
            "severity": severity,
            "urgency": urgency,
            "certainty": certainty,
            "headline": headline,
            "description_text": description_text,
            "effective_at": _iso(eff_dt) if eff_dt is not None else None,
            "expires_at": _iso(exp_dt) if exp_dt is not None else None,
            "status": status,
            "ingested_at": _iso(ing_dt),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        alerts.append(row)
        _save("weather_alerts.json", alerts)

        client["last_seen_at"] = _iso(now)
        client["updated_at"] = _iso(now)
        _save("api_clients.json", api_clients)

        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(
            request_logs,
            client.get("id"),
            {"state": state_u, "upstream_provider": upstream_provider, "upstream_alert_id": upstream_alert_id},
            200,
            False,
            latency,
            None,
        )
        return {"data": row}

    # Update in-place (idempotent)
    old_status = existing.get("status")
    if old_status not in transitions:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(request_logs, client.get("id"), {"state": state_u}, 409, False, latency, "CONFLICT")
        return _err("CONFLICT", "Existing alert has invalid status in datastore", status=old_status)

    if status != old_status:
        if status not in transitions.get(old_status, set()):
            latency = int((time.perf_counter() - t0) * 1000)
            _log_request(request_logs, client.get("id"), {"state": state_u}, 409, False, latency, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition weather_alerts.status from {old_status} to {status}")

    # Apply updates
    existing["state"] = state_u
    existing["event"] = event
    existing["severity"] = severity
    existing["urgency"] = urgency
    existing["certainty"] = certainty
    existing["headline"] = headline
    existing["description_text"] = description_text
    existing["effective_at"] = _iso(eff_dt) if eff_dt is not None else None
    existing["expires_at"] = _iso(exp_dt) if exp_dt is not None else None
    existing["status"] = status
    existing["ingested_at"] = _iso(ing_dt)
    existing["updated_at"] = _iso(now)

    _save("weather_alerts.json", alerts)

    client["last_seen_at"] = _iso(now)
    client["updated_at"] = _iso(now)
    _save("api_clients.json", api_clients)

    latency = int((time.perf_counter() - t0) * 1000)
    _log_request(
        request_logs,
        client.get("id"),
        {"state": state_u, "upstream_provider": upstream_provider, "upstream_alert_id": upstream_alert_id},
        200,
        False,
        latency,
        None,
    )

    return {"data": existing}

def upsert_forecast_point(api_key, upstream_provider, grid_id, grid_x, grid_y, latitude, longitude, status, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0106000" if __import__("os").path.isdir("./environment_mix/0106000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.astimezone(datetime.timezone.utc) if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _auth_client(api_key_value):
        # Authenticate by matching provided value against stored client-visible value(s):
        # - accept client id
        # - accept exact api_key_hash value (store uses hashes; vendor client passes that string)
        if not isinstance(api_key_value, str) or not api_key_value:
            return None
        clients = _load("api_clients.json")
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("id") == api_key_value or c.get("api_key_hash") == api_key_value:
                return c
        return None

    def _enforce_quota(client_row):
        if not isinstance(client_row, dict):
            return (False, "UNAUTHORIZED", 401, "UNAUTHORIZED")
        if client_row.get("status") != "active":
            # Not allowed to consume tools; log attempt.
            return (False, "UNAUTHORIZED", 403, "CLIENT_NOT_ACTIVE")

        client_id = client_row.get("id")
        if not isinstance(client_id, str) or not client_id:
            return (False, "UNAUTHORIZED", 401, "UNAUTHORIZED")

        logs = _load("request_logs.json")
        minute_quota = client_row.get("quota_requests_per_minute")
        day_quota = client_row.get("quota_requests_per_day")

        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(day_quota, int) or day_quota < 0:
            day_quota = 0

        window_min_start = now - datetime.timedelta(minutes=1)
        window_day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

        def _ts(row):
            dt = _parse_rfc3339(row.get("created_at"))
            return dt

        last_min = 0
        last_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_client_id") != client_id:
                continue
            dt = _ts(r)
            if not isinstance(dt, datetime.datetime):
                continue
            if dt >= window_min_start:
                last_min += 1
            if dt >= window_day_start:
                last_day += 1

        if minute_quota == 0 or last_min >= minute_quota:
            return (False, "RATE_LIMIT", 429, "RATE_LIMITED")
        if day_quota == 0 or last_day >= day_quota:
            return (False, "QUOTA_EXCEEDED", 429, "QUOTA_EXCEEDED")
        return (True, None, None, None)

    def _append_log(api_client_id, params_obj, http_status, served_from_cache, error_code=None):
        logs = _load("request_logs.json")
        latency_ms = max(0, int((time.time() - t0) * 1000))
        created = _iso(datetime.datetime.now(datetime.timezone.utc))
        row = {
            "id": _new_id("wthr_req"),
            "api_client_id": api_client_id,
            "tool_name": "get-forecast",  # schema enum restriction
            "params": params_obj,
            "state": None,
            "latitude": None,
            "longitude": None,
            "response_status_code": int(http_status),
            "served_from_cache": bool(served_from_cache),
            "latency_ms": int(latency_ms),
            "error_code": error_code,
            "created_at": created,
            "updated_at": created,
        }
        # maintain schema constraint: lat/lon iff tool_name='get-forecast'
        lat = params_obj.get("latitude")
        lon = params_obj.get("longitude")
        if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
            row["latitude"] = float(lat)
            row["longitude"] = float(lon)
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs first
    if not isinstance(api_key, str) or not api_key:
        _append_log(None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is required.")

    if upstream_provider not in ("nws", "meteo", "other"):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "upstream_provider must be one of: nws, meteo, other.")

    if not isinstance(grid_id, str) or not grid_id.strip():
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "grid_id is required.")

    if not isinstance(grid_x, int) or grid_x < 0:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "grid_x must be an integer >= 0.")

    if not isinstance(grid_y, int) or grid_y < 0:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "grid_y must be an integer >= 0.")

    if not isinstance(latitude, (int, float)) or latitude < -90 or latitude > 90:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "latitude must be a number between -90 and 90.")

    if not isinstance(longitude, (int, float)) or longitude < -180 or longitude > 180:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "longitude must be a number between -180 and 180.")

    if status not in ("active", "deprecated"):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated.")

    # Authenticate + quota
    client = _auth_client(api_key)
    if not isinstance(client, dict):
        _append_log(None, {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    allowed, err_code, http_status, log_err = _enforce_quota(client)
    if not allowed:
        _append_log(client.get("id"), {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": latitude, "longitude": longitude, "status": status}, http_status, False, log_err)
        return _err(err_code, "Request not permitted.", detail=log_err)

    # Upsert
    points = _load("forecast_points.json")
    if not isinstance(points, list):
        points = []

    key = (upstream_provider, grid_id, grid_x, grid_y)
    existing = None
    existing_idx = None
    for i, p in enumerate(points):
        if not isinstance(p, dict):
            continue
        if (p.get("upstream_provider"), p.get("grid_id"), p.get("grid_x"), p.get("grid_y")) == key:
            existing = p
            existing_idx = i
            break

    created_iso = _iso(now)
    if existing is None:
        # Create
        row = {
            "id": _new_id("wthr_pt"),
            "upstream_provider": upstream_provider,
            "grid_id": grid_id,
            "grid_x": int(grid_x),
            "grid_y": int(grid_y),
            "latitude": float(latitude),
            "longitude": float(longitude),
            "status": status,
            "created_at": created_iso,
            "updated_at": created_iso,
        }
        points.append(row)
        _save("forecast_points.json", points)
        _append_log(client.get("id"), {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": float(latitude), "longitude": float(longitude), "status": status}, 200, True, None)
        return {"forecast_point": row}

    # Update with lifecycle transition enforcement
    cur_status = existing.get("status")
    if cur_status not in ("active", "deprecated"):
        # If corrupted, treat as validation error
        _append_log(client.get("id"), {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": float(latitude), "longitude": float(longitude), "status": status}, 409, True, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Existing point has invalid status '{cur_status}'.")

    transitions = {"active": ["deprecated"], "deprecated": []}
    if status != cur_status and status not in transitions.get(cur_status, []):
        _append_log(client.get("id"), {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": float(latitude), "longitude": float(longitude), "status": status}, 409, True, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition forecast_points.status from '{cur_status}' to '{status}'.")

    # Apply updates (idempotent if no change)
    updated = dict(existing)
    updated["latitude"] = float(latitude)
    updated["longitude"] = float(longitude)
    updated["status"] = status
    updated["updated_at"] = created_iso
    points[existing_idx] = updated
    _save("forecast_points.json", points)
    _append_log(client.get("id"), {"upstream_provider": upstream_provider, "grid_id": grid_id, "grid_x": grid_x, "grid_y": grid_y, "latitude": float(latitude), "longitude": float(longitude), "status": status}, 200, True, None)
    return {"forecast_point": updated}

