            "params": params_obj,
            "state": None,
            "latitude": None,
            "longitude": None,
            "response_status_code": int(http_status),
            "served_from_cache": bool(served_from_cache),
            "latency_ms": int(latency_ms),
            "error_code": error_code,
            "created_at": created,
            "updated_at": created,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key:
        _append_log(None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is required.")

    if not isinstance(forecast_point_id, str) or not forecast_point_id.strip():
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "forecast_point_id is required.")

    dt_issued = _parse_rfc3339(issued_at)
    if dt_issued is None:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issued_at must be an RFC3339 datetime string.")

    dt_from = _parse_rfc3339(valid_from) if valid_from is not None else None
    if valid_from is not None and dt_from is None:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "valid_from must be RFC3339 datetime or null.")

    dt_to = _parse_rfc3339(valid_to) if valid_to is not None else None
    if valid_to is not None and dt_to is None:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "valid_to must be RFC3339 datetime or null.")

    if dt_from is not None and dt_to is not None and dt_from > dt_to:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "valid_from must be <= valid_to when both are provided.")

    if status not in ("available", "superseded", "failed"):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: available, superseded, failed.")

    if not isinstance(periods, list):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "periods must be an array.")

    if status == "available" and len(periods) == 0:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "periods must be non-empty when status='available'.")

    if raw_payload is not None and not isinstance(raw_payload, dict):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "raw_payload must be an object or null.")

    dt_ingested = _parse_rfc3339(ingested_at) if ingested_at is not None else None
    if ingested_at is not None and dt_ingested is None:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ingested_at must be RFC3339 datetime or null.")

    # Authenticate + quota
    client = _auth_client(api_key)
    if not isinstance(client, dict):
        _append_log(None, {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    allowed, err_code, http_status, log_err = _enforce_quota(client)
    if not allowed:
        _append_log(client.get("id"), {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, http_status, False, log_err)
        return _err(err_code, "Request not permitted.", detail=log_err)

    # Foreign key: forecast_point_id must exist
    points = _load("forecast_points.json")
    point_exists = False
    for p in points if isinstance(points, list) else []:
        if isinstance(p, dict) and p.get("id") == forecast_point_id:
            point_exists = True
            break
    if not point_exists:
        _append_log(client.get("id"), {"forecast_point_id": forecast_point_id, "issued_at": issued_at, "valid_from": valid_from, "valid_to": valid_to, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_at}, 404, False, "NOT_FOUND")
        return _err("NOT_FOUND", "forecast_point_id does not exist.")

    forecasts = _load("forecasts.json")
    if not isinstance(forecasts, list):
        forecasts = []

    issued_iso = _iso(dt_issued)
    from_iso = _iso(dt_from) if dt_from is not None else None
    to_iso = _iso(dt_to) if dt_to is not None else None
    ingested_iso = _iso(dt_ingested) if dt_ingested is not None else _iso(now)

    # Idempotent on unique(forecast_point_id, issued_at)
    existing = None
    existing_idx = None
    for i, f in enumerate(forecasts):
        if not isinstance(f, dict):
            continue
        if f.get("forecast_point_id") == forecast_point_id and f.get("issued_at") == issued_iso:
            existing = f
            existing_idx = i
            break

    if existing is None:
        row = {
            "id": _new_id("wthr_fcst"),
            "forecast_point_id": forecast_point_id,
            "issued_at": issued_iso,
            "valid_from": from_iso,
            "valid_to": to_iso,
            "status": status,
            "periods": periods,
            "raw_payload": raw_payload,
            "ingested_at": ingested_iso,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        forecasts.append(row)

        # Supersede prior forecasts if inserting as available
        if status == "available":
            new_dt = dt_issued
            for j in range(len(forecasts) - 1):
                f = forecasts[j]
                if not isinstance(f, dict):
                    continue
                if f.get("forecast_point_id") != forecast_point_id:
                    continue
                if f.get("status") != "available":
                    continue
                old_dt = _parse_rfc3339(f.get("issued_at"))
                if isinstance(old_dt, datetime.datetime) and old_dt < new_dt:
                    f["status"] = "superseded"
                    f["updated_at"] = _iso(now)

        _save("forecasts.json", forecasts)
        _append_log(client.get("id"), {"forecast_point_id": forecast_point_id, "issued_at": issued_iso, "valid_from": from_iso, "valid_to": to_iso, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_iso}, 200, True, None)
        return {"forecast": row}

    # Update existing (allowed for idempotent ingestion)
    updated = dict(existing)
    updated["valid_from"] = from_iso
    updated["valid_to"] = to_iso
    updated["status"] = status
    updated["periods"] = periods
    updated["raw_payload"] = raw_payload
    updated["ingested_at"] = ingested_iso
    updated["updated_at"] = _iso(now)

    # Lifecycle transitions for forecasts: available -> superseded only; superseded/failed terminal.
    transitions = {"available": ["superseded"], "superseded": [], "failed": []}
    cur_status = existing.get("status")
    if cur_status in transitions and status != cur_status:
        if status not in transitions.get(cur_status, []):
            _append_log(client.get("id"), {"forecast_point_id": forecast_point_id, "issued_at": issued_iso, "valid_from": from_iso, "valid_to": to_iso, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_iso}, 409, True, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition forecasts.status from '{cur_status}' to '{status}'.")

    forecasts[existing_idx] = updated

    # If (still) available, supersede older available ones
    if status == "available":
        new_dt = dt_issued
        for j, f in enumerate(forecasts):
            if j == existing_idx or not isinstance(f, dict):
                continue
            if f.get("forecast_point_id") != forecast_point_id:
                continue
            if f.get("status") != "available":
                continue
            old_dt = _parse_rfc3339(f.get("issued_at"))
            if isinstance(old_dt, datetime.datetime) and old_dt < new_dt:
                f["status"] = "superseded"
                f["updated_at"] = _iso(now)

    _save("forecasts.json", forecasts)
    _append_log(client.get("id"), {"forecast_point_id": forecast_point_id, "issued_at": issued_iso, "valid_from": from_iso, "valid_to": to_iso, "status": status, "periods": periods, "raw_payload": raw_payload, "ingested_at": ingested_iso}, 200, True, None)
    return {"forecast": updated}

def list_request_logs(api_key, tool_name=None, response_status_code=None, created_at_gte=None, created_at_lte=None, served_from_cache=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, uuid, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0106000" if __import__("os").path.isdir("./environment_mix/0106000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.astimezone(datetime.timezone.utc) if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _encode_cursor(created_at_iso, rid):
        payload = json.dumps({"created_at": created_at_iso, "id": rid}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8"))
        obj = json.loads(raw.decode("utf-8"))
        if not isinstance(obj, dict):
            return None
        if "created_at" not in obj or "id" not in obj:
            return None
        if not isinstance(obj.get("created_at"), str) or not isinstance(obj.get("id"), str):
            return None
        return obj

    def _auth_client(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value:
            return None
        clients = _load("api_clients.json")
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("id") == api_key_value or c.get("api_key_hash") == api_key_value:
                return c
        return None

    def _enforce_quota(client_row):
        # Listing logs also counts towards quota per business rules ("EVERY call")
        if not isinstance(client_row, dict):
            return (False, "UNAUTHORIZED", 401, "UNAUTHORIZED")
        if client_row.get("status") != "active":
            return (False, "UNAUTHORIZED", 403, "CLIENT_NOT_ACTIVE")

        client_id = client_row.get("id")
        if not isinstance(client_id, str) or not client_id:
            return (False, "UNAUTHORIZED", 401, "UNAUTHORIZED")

        logs = _load("request_logs.json")
        minute_quota = client_row.get("quota_requests_per_minute")
        day_quota = client_row.get("quota_requests_per_day")
        if not isinstance(minute_quota, int) or minute_quota < 0:
            minute_quota = 0
        if not isinstance(day_quota, int) or day_quota < 0:
            day_quota = 0

        window_min_start = now - datetime.timedelta(minutes=1)
        window_day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

        last_min = 0
        last_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("api_client_id") != client_id:
                continue
            dt = _parse_rfc3339(r.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                continue
            if dt >= window_min_start:
                last_min += 1
            if dt >= window_day_start:
                last_day += 1

        if minute_quota == 0 or last_min >= minute_quota:
            return (False, "RATE_LIMIT", 429, "RATE_LIMITED")
        if day_quota == 0 or last_day >= day_quota:
            return (False, "QUOTA_EXCEEDED", 429, "QUOTA_EXCEEDED")
        return (True, None, None, None)

    def _append_log(api_client_id, params_obj, http_status, served_from_cache, error_code=None):
        logs = _load("request_logs.json")
        latency_ms = max(0, int((time.time() - t0) * 1000))
        created = _iso(datetime.datetime.now(datetime.timezone.utc))
        row = {
            "id": _new_id("wthr_req"),
            "api_client_id": api_client_id,
            "tool_name": "get-forecast",  # schema enum restriction; log under a valid tool
            "params": params_obj,
            "state": None,
            "latitude": None,
            "longitude": None,
            "response_status_code": int(http_status),
            "served_from_cache": bool(served_from_cache),
            "latency_ms": int(latency_ms),
            "error_code": error_code,
            "created_at": created,
            "updated_at": created,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate filters (do not require they match anything)
    if not isinstance(api_key, str) or not api_key:
        _append_log(None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is required.")

    if tool_name is not None and tool_name not in ("get-alerts", "get-forecast"):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tool_name must be one of: get-alerts, get-forecast.")

    if response_status_code is not None:
        if not isinstance(response_status_code, int) or response_status_code < 100 or response_status_code > 599:
            client = _auth_client(api_key)
            _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "response_status_code must be an integer between 100 and 599.")

    dt_gte = _parse_rfc3339(created_at_gte) if created_at_gte is not None else None
    if created_at_gte is not None and dt_gte is None:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_at_gte must be RFC3339 datetime.")

    dt_lte = _parse_rfc3339(created_at_lte) if created_at_lte is not None else None
    if created_at_lte is not None and dt_lte is None:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_at_lte must be RFC3339 datetime.")

    if dt_gte is not None and dt_lte is not None and dt_gte > dt_lte:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_at_gte must be <= created_at_lte.")

    if served_from_cache is not None and not isinstance(served_from_cache, bool):
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "served_from_cache must be boolean when provided.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        client = _auth_client(api_key)
        _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")

    cur_obj = None
    if cursor is not None:
        try:
            cur_obj = _decode_cursor(cursor)
        except Exception:
            cur_obj = None
        if cur_obj is None:
            client = _auth_client(api_key)
            _append_log(client.get("id") if isinstance(client, dict) else None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Authenticate
    client = _auth_client(api_key)
    if not isinstance(client, dict):
        _append_log(None, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Quota (still log if rejected)
    allowed, err_code, http_status, log_err = _enforce_quota(client)
    if not allowed:
        _append_log(client.get("id"), {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, http_status, False, log_err)
        return _err(err_code, "Request not permitted.", detail=log_err)

    # Filter rows belonging to this api_client_id
    all_logs = _load("request_logs.json")
    if not isinstance(all_logs, list):
        all_logs = []
    client_id = client.get("id")

    rows = []
    for r in all_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_client_id") != client_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if response_status_code is not None and r.get("response_status_code") != response_status_code:
            continue
        if served_from_cache is not None and bool(r.get("served_from_cache")) != served_from_cache:
            continue
        dt = _parse_rfc3339(r.get("created_at"))
        if dt_gte is not None and (dt is None or dt < dt_gte):
            continue
        if dt_lte is not None and (dt is None or dt > dt_lte):
            continue
        rows.append(r)

    # Order by created_at desc, id desc
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # Cursor pagination
    if cur_obj is not None:
        cur_dt = _parse_rfc3339(cur_obj.get("created_at"))
        cur_id = cur_obj.get("id")
        if cur_dt is None or not isinstance(cur_id, str):
            _append_log(client_id, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 400, True, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        filtered = []
        for r in rows:
            dt = _parse_rfc3339(r.get("created_at"))
            rid = str(r.get("id") or "")
            if dt is None:
                continue
            # since descending: return items strictly "after" the cursor
            if dt < cur_dt or (dt == cur_dt and rid < cur_id):
                filtered.append(r)
        rows = filtered

    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("created_at"), str(last.get("id") or ""))

    _append_log(client_id, {"tool_name": tool_name, "response_status_code": response_status_code, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "served_from_cache": served_from_cache, "limit": limit, "cursor": cursor}, 200, True, None)
    return {
        "request_logs": page,
        "meta": {
            "limit": limit,
            "total": len(rows) if cur_obj is None else None,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
    }
